use axum::{
    body::Body,
    extract::{Path, Query},
    http::{HeaderMap, StatusCode},
    response::{Html, IntoResponse, Response},
    routing::{get, post},
    Router,
};
use clap::{Parser, ValueEnum};
use serde::{Deserialize, Serialize};
use std::net::{IpAddr, Ipv4Addr, SocketAddr};
use std::path::PathBuf;
use std::sync::Arc;
use tokio::fs;
use tower_http::trace::TraceLayer;

mod cli;
mod server;
mod handlers;
mod auth;
mod utils;

use cli::Args;
use server::AppState;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    // Initialize logging if verbose
    if args.verbose {
        env_logger::builder()
            .filter_level(log::LevelFilter::Info)
            .try_init()
            .ok();
    }

    // Determine the path to serve
    let serve_path = if let Some(path) = &args.path {
        PathBuf::from(path)
    } else {
        std::env::current_dir()?
    };

    // Verify path exists
    if !serve_path.exists() {
        eprintln!("Error: Path does not exist: {:?}", serve_path);
        std::process::exit(1);
    }

    // Parse interfaces
    let interfaces = parse_interfaces(&args.interfaces);

    // Create app state
    let state = Arc::new(AppState {
        serve_path: serve_path.clone(),
        auth: args.auth.clone(),
        index: args.index.clone(),
        spa: args.spa,
        verbose: args.verbose,
        port: args.port,
        color_scheme: args.color_scheme.clone(),
        color_scheme_dark: args.color_scheme_dark.clone(),
        title: args.title.clone(),
        hide_version_footer: args.hide_version_footer,
        hide_theme_selector: args.hide_theme_selector,
        default_sorting_method: args.default_sorting_method.clone(),
        default_sorting_order: args.default_sorting_order.clone(),
        dirs_first: args.dirs_first,
    });

    // Build router
    let app = Router::new()
        .route("/", get(handlers::root))
        .route("/*path", get(handlers::serve_file))
        .layer(TraceLayer::new_for_http())
        .with_state(state);

    // Create socket address
    let addr = SocketAddr::new(
        interfaces.get(0).copied().unwrap_or(IpAddr::from(Ipv4Addr::new(0, 0, 0, 0))),
        args.port,
    );

    // Print startup info
    println!("miniserve v{}", env!("CARGO_PKG_VERSION"));
    println!("Bound to [::]:{}. 0.0.0.0:{}", args.port, args.port);
    println!("Serving path {}", serve_path.display());
    println!("Available at (non-exhaustive list):");

    for ip in &interfaces {
        println!("    http://{}:{}", ip, args.port);
    }
    if interfaces.is_empty() {
        println!("    http://127.0.0.1:{}", args.port);
    }

    // Start server
    let listener = tokio::net::TcpListener::bind(addr).await?;

    axum::serve(listener, app).await?;

    Ok(())
}

fn parse_interfaces(interfaces: &Option<String>) -> Vec<IpAddr> {
    if let Some(ifaces) = interfaces {
        ifaces
            .split(',')
            .filter_map(|s| s.trim().parse::<IpAddr>().ok())
            .collect()
    } else {
        // Default interfaces
        vec![
            IpAddr::from([127, 0, 0, 1]),
            IpAddr::from([0, 0, 0, 0]),
        ]
    }
}
