use clap::{Parser, ValueEnum};
use std::path::PathBuf;

#[derive(Parser, Debug, Clone)]
#[command(
    name = "miniserve",
    about = "For when you really just want to serve some files over HTTP right now!",
    long_about = "miniserve - serve files and directories over HTTP"
)]
pub struct Args {
    /// Which path to serve
    #[arg(env = "MINISERVE_PATH")]
    pub path: Option<PathBuf>,

    /// Be verbose, includes emitting access logs
    #[arg(short, long, env = "MINISERVE_VERBOSE")]
    pub verbose: bool,

    /// Port to use
    #[arg(short, long, default_value = "8080", env = "MINISERVE_PORT")]
    pub port: u16,

    /// Interface to listen on
    #[arg(short, long, env = "MINISERVE_INTERFACE")]
    pub interfaces: Option<String>,

    /// The name of a directory index file to serve
    #[arg(long, env = "MINISERVE_INDEX")]
    pub index: Option<String>,

    /// Activate SPA (Single Page Application) mode
    #[arg(long, env = "MINISERVE_SPA")]
    pub spa: bool,

    /// Set authentication (username:password format)
    #[arg(short, long, env = "MINISERVE_AUTH")]
    pub auth: Option<String>,

    /// Default color scheme
    #[arg(short, long, default_value = "squirrel", env = "MINISERVE_COLOR_SCHEME")]
    pub color_scheme: String,

    /// Default color scheme for dark mode
    #[arg(short = 'd', long, default_value = "archlinux", env = "MINISERVE_COLOR_SCHEME_DARK")]
    pub color_scheme_dark: String,

    /// Shown instead of host in page title and heading
    #[arg(short, long, env = "MINISERVE_TITLE")]
    pub title: Option<String>,

    /// Hide version footer
    #[arg(short = 'F', long, env = "MINISERVE_HIDE_VERSION_FOOTER")]
    pub hide_version_footer: bool,

    /// Hide theme selector
    #[arg(long, env = "MINISERVE_HIDE_THEME_SELECTOR")]
    pub hide_theme_selector: bool,

    /// Default sorting method
    #[arg(short = 'S', long, default_value = "name", env = "MINISERVE_DEFAULT_SORTING_METHOD")]
    pub default_sorting_method: String,

    /// Default sorting order
    #[arg(short = 'O', long, default_value = "desc", env = "MINISERVE_DEFAULT_SORTING_ORDER")]
    pub default_sorting_order: String,

    /// List directories first
    #[arg(short = 'D', long, env = "MINISERVE_DIRS_FIRST")]
    pub dirs_first: bool,

    /// Pretty URLs mode
    #[arg(long, env = "MINISERVE_PRETTY_URLS")]
    pub pretty_urls: bool,

    /// Show symlink info
    #[arg(short = 'l', long, env = "MINISERVE_SHOW_SYMLINK_INFO")]
    pub show_symlink_info: bool,

    /// No symlinks
    #[arg(short = 'P', long, env = "MINISERVE_NO_SYMLINKS")]
    pub no_symlinks: bool,

    /// Show hidden files
    #[arg(short = 'H', long, env = "MINISERVE_HIDDEN")]
    pub hidden: bool,

    /// Enable QR code
    #[arg(short = 'q', long, env = "MINISERVE_QRCODE")]
    pub qrcode: bool,

    /// Enable tar archive generation
    #[arg(short = 'r', long, env = "MINISERVE_ENABLE_TAR")]
    pub enable_tar: bool,

    /// Enable tar.gz archive generation
    #[arg(short = 'g', long, env = "MINISERVE_ENABLE_TAR_GZ")]
    pub enable_tar_gz: bool,

    /// Enable zip archive generation
    #[arg(short = 'z', long, env = "MINISERVE_ENABLE_ZIP")]
    pub enable_zip: bool,

    /// Compress response
    #[arg(short = 'C', long, env = "MINISERVE_COMPRESS_RESPONSE")]
    pub compress_response: bool,

    /// Disable indexing
    #[arg(short = 'I', long, env = "MINISERVE_DISABLE_INDEXING")]
    pub disable_indexing: bool,

    /// TLS certificate file
    #[arg(long, env = "MINISERVE_TLS_CERT")]
    pub tls_cert: Option<PathBuf>,

    /// TLS key file
    #[arg(long, env = "MINISERVE_TLS_KEY")]
    pub tls_key: Option<PathBuf>,

    /// Enable WebDAV support
    #[arg(long, env = "MINISERVE_ENABLE_WEBDAV")]
    pub enable_webdav: bool,

    /// Show version
    #[arg(short = 'V', long)]
    pub version: bool,
}
