use axum::{
    body::Body,
    extract::{Path, State},
    http::StatusCode,
    response::{Html, IntoResponse, Response},
};
use std::sync::Arc;
use tokio::fs;

use crate::server::AppState;

pub async fn root(State(state): State<Arc<AppState>>) -> Response {
    serve_file(Path(String::new()), State(state)).await
}

pub async fn serve_file(
    Path(path): Path<String>,
    State(state): State<Arc<AppState>>,
) -> Response {
    let mut request_path = state.serve_path.clone();

    if !path.is_empty() {
        request_path.push(&path);
    }

    // Check if path is a directory
    match fs::metadata(&request_path).await {
        Ok(metadata) => {
            if metadata.is_dir() {
                // Check for index file
                if let Some(index) = &state.index {
                    let index_path = request_path.join(index);
                    match fs::read_to_string(&index_path).await {
                        Ok(content) => Html(content).into_response(),
                        Err(_) => {
                            if state.disable_indexing {
                                StatusCode::NOT_FOUND.into_response()
                            } else {
                                // Generate directory listing
                                generate_dir_listing(&request_path, &path, state).await
                            }
                        }
                    }
                } else if state.disable_indexing {
                    StatusCode::NOT_FOUND.into_response()
                } else {
                    // Generate directory listing
                    generate_dir_listing(&request_path, &path, state).await
                }
            } else {
                // Serve file
                match fs::read(&request_path).await {
                    Ok(content) => {
                        let mime = mime_guess::from_path(&request_path).first_or_octet_stream();
                        ([(axum::http::header::CONTENT_TYPE, mime.as_ref())], content)
                            .into_response()
                    }
                    Err(_) => StatusCode::NOT_FOUND.into_response(),
                }
            }
        }
        Err(_) => {
            if state.spa {
                // In SPA mode, serve index for non-existent paths
                if let Some(index) = &state.index {
                    let index_path = state.serve_path.join(index);
                    match fs::read_to_string(&index_path).await {
                        Ok(content) => Html(content).into_response(),
                        Err(_) => StatusCode::NOT_FOUND.into_response(),
                    }
                } else {
                    StatusCode::NOT_FOUND.into_response()
                }
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
    }
}

async fn generate_dir_listing(
    dir_path: &std::path::Path,
    request_path: &str,
    state: &AppState,
) -> Response {
    match fs::read_dir(dir_path).await {
        Ok(mut entries) => {
            let mut files = Vec::new();
            let mut dirs = Vec::new();

            while let Ok(Some(entry)) = entries.next_entry().await {
                if let Ok(metadata) = entry.metadata().await {
                    let file_name = entry.file_name();
                    let name = file_name.to_string_lossy().to_string();

                    if name.starts_with('.') && !state.hidden {
                        continue;
                    }

                    if metadata.is_dir() {
                        dirs.push(name);
                    } else {
                        let size = metadata.len();
                        files.push((name, size));
                    }
                }
            }

            // Sort
            dirs.sort();
            files.sort_by(|a, b| a.0.cmp(&b.0));

            // Generate HTML
            let mut html = String::from("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Directory Listing</title></head><body>");
            html.push_str("<h1>Directory Listing</h1>");
            html.push_str("<ul>");

            // Add parent directory link if not root
            if request_path != "" && request_path != "/" {
                html.push_str("<li><a href=\"..\">..</a></li>");
            }

            // Add directories
            for dir in dirs {
                html.push_str(&format!("<li><a href=\"{}\">{}/</a></li>", dir, dir));
            }

            // Add files
            for (file, size) in files {
                html.push_str(&format!("<li><a href=\"{}\">{}</a> ({})</li>", file, file, size));
            }

            html.push_str("</ul></body></html>");
            Html(html).into_response()
        }
        Err(_) => StatusCode::NOT_FOUND.into_response(),
    }
}
