use std::path::PathBuf;
use std::sync::Arc;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::fs;
use crate::server::AppState;

pub async fn handle_connection(
    mut socket: TcpStream,
    state: Arc<AppState>,
) -> anyhow::Result<()> {
    let mut buffer = vec![0; 4096];
    let n = socket.read(&mut buffer).await?;

    if n == 0 {
        return Ok(());
    }

    let request = String::from_utf8_lossy(&buffer[..n]);
    let lines: Vec<&str> = request.lines().collect();

    if lines.is_empty() {
        return Ok(());
    }

    let request_line = lines[0];
    let parts: Vec<&str> = request_line.split_whitespace().collect();

    if parts.len() < 2 {
        return Ok(());
    }

    let method = parts[0];
    let path = parts[1];

    if method != "GET" && method != "HEAD" {
        send_error(&mut socket, 405, "Method Not Allowed").await?;
        return Ok(());
    }

    // Parse the path
    let clean_path = parse_path(path);

    // Build the full file path
    let mut file_path = state.serve_path.clone();
    if !clean_path.is_empty() && clean_path != "/" {
        file_path.push(clean_path.trim_start_matches('/'));
    }

    // Serve the file/directory
    match fs::metadata(&file_path).await {
        Ok(metadata) => {
            if metadata.is_dir() {
                // Check for index file
                if let Some(index) = &state.index {
                    let index_path = file_path.join(index);
                    match fs::read_to_string(&index_path).await {
                        Ok(content) => {
                            send_response(&mut socket, 200, "text/html", &content).await?;
                        }
                        Err(_) => {
                            if state.disable_indexing {
                                send_error(&mut socket, 404, "Not Found").await?;
                            } else {
                                let listing = generate_dir_listing(&file_path, &clean_path, &state).await?;
                                send_response(&mut socket, 200, "text/html", &listing).await?;
                            }
                        }
                    }
                } else if state.disable_indexing {
                    send_error(&mut socket, 404, "Not Found").await?;
                } else {
                    let listing = generate_dir_listing(&file_path, &clean_path, &state).await?;
                    send_response(&mut socket, 200, "text/html", &listing).await?;
                }
            } else {
                // Serve file
                match fs::read(&file_path).await {
                    Ok(content) => {
                        let mime = mime_guess::from_path(&file_path)
                            .first_or_octet_stream()
                            .as_ref()
                            .to_string();

                        let response = format!(
                            "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                            mime,
                            content.len()
                        );

                        socket.write_all(response.as_bytes()).await?;
                        if method == "GET" {
                            socket.write_all(&content).await?;
                        }
                    }
                    Err(_) => send_error(&mut socket, 404, "Not Found").await?,
                }
            }
        }
        Err(_) => {
            if state.spa {
                // In SPA mode, serve index for non-existent paths
                if let Some(index) = &state.index {
                    let index_path = state.serve_path.join(index);
                    match fs::read_to_string(&index_path).await {
                        Ok(content) => {
                            send_response(&mut socket, 200, "text/html", &content).await?;
                        }
                        Err(_) => send_error(&mut socket, 404, "Not Found").await?,
                    }
                } else {
                    send_error(&mut socket, 404, "Not Found").await?;
                }
            } else {
                send_error(&mut socket, 404, "Not Found").await?;
            }
        }
    }

    Ok(())
}

async fn send_response(
    socket: &mut TcpStream,
    status: u16,
    content_type: &str,
    content: &str,
) -> anyhow::Result<()> {
    let response = format!(
        "HTTP/1.1 {} OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        status,
        content_type,
        content.len(),
        content
    );

    socket.write_all(response.as_bytes()).await?;
    Ok(())
}

async fn send_error(
    socket: &mut TcpStream,
    status: u16,
    status_text: &str,
) -> anyhow::Result<()> {
    let body = format!("<html><body><h1>{} {}</h1></body></html>", status, status_text);
    let response = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        status,
        status_text,
        body.len(),
        body
    );

    socket.write_all(response.as_bytes()).await?;
    Ok(())
}

async fn generate_dir_listing(
    dir_path: &std::path::Path,
    request_path: &str,
    state: &AppState,
) -> anyhow::Result<String> {
    let mut entries_list = Vec::new();

    match fs::read_dir(dir_path).await {
        Ok(mut dir_entries) => {
            while let Ok(Some(entry)) = dir_entries.next_entry().await {
                if let Ok(metadata) = entry.metadata().await {
                    let file_name = entry.file_name();
                    let name = file_name.to_string_lossy().to_string();

                    if name.starts_with('.') && !state.hidden {
                        continue;
                    }

                    if metadata.is_dir() {
                        entries_list.push((name, true, 0));
                    } else {
                        let size = metadata.len();
                        entries_list.push((name, false, size));
                    }
                }
            }
        }
        Err(_) => {}
    }

    // Sort
    entries_list.sort_by(|a, b| {
        // Directories first if enabled
        if state.dirs_first {
            if a.1 != b.1 {
                return if a.1 { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater };
            }
        }
        a.0.cmp(&b.0)
    });

    // Generate HTML
    let mut html = String::from(
        "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<title>Directory Listing</title>\n<style>\nbody { font-family: monospace; }\ntable { border-collapse: collapse; width: 100%; }\nth, td { text-align: left; padding: 5px; border-bottom: 1px solid #ddd; }\n</style>\n</head>\n<body>\n"
    );

    html.push_str("<h1>Directory Listing</h1>\n");
    html.push_str("<table>\n<tr><th>Name</th><th>Size</th><th>Modified</th></tr>\n");

    // Add parent directory link if not root
    if request_path != "" && request_path != "/" {
        html.push_str("<tr><td><a href=\"..\">..</a></td><td>-</td><td>-</td></tr>\n");
    }

    // Add entries
    for (name, is_dir, size) in entries_list {
        if is_dir {
            html.push_str(&format!("<tr><td><a href=\"{}\">{}/</a></td><td>-</td><td>-</td></tr>\n", name, name));
        } else {
            html.push_str(&format!("<tr><td><a href=\"{}\">{}</a></td><td>{}</td><td>-</td></tr>\n", name, name, size));
        }
    }

    html.push_str("</table>\n</body>\n</html>\n");

    Ok(html)
}

fn parse_path(path: &str) -> String {
    // Remove query string
    let clean = if let Some(idx) = path.find('?') {
        &path[..idx]
    } else {
        path
    };

    // Decode URL encoding
    urlencoding::decode(clean)
        .unwrap_or_else(|_| clean.into())
        .to_string()
}
