fn serve_request(
    stream: &mut TcpStream,
    serve_path: &Path,
    request_path: &str,
    disable_indexing: bool,
    index: Option<&str>,
    spa: bool,
    head_only: bool,
) {
    // Parse path
    let clean_path = parse_path(request_path);

    // Build file path
    let mut file_path = serve_path.to_path_buf();
    if !clean_path.is_empty() && clean_path != "/" {
