                } else {
                    let listing = generate_dir_listing(&file_path, &clean_path);
                    send_response(stream, 200, "text/html", &listing, head_only);
                }
            } else {
                // Serve file
                match fs::read(&file_path) {
                    Ok(content) => {
                        let mime = guess_mime_type(&file_path);
                        send_response_bytes(stream, 200, &mime, &content, head_only);
                    }
