    if let Ok(dir_entries) = fs::read_dir(dir_path) {
        for entry in dir_entries.flatten() {
            if let Ok(metadata) = entry.metadata() {
                let file_name = entry.file_name();
                let name = file_name.to_string_lossy().to_string();

                if name.starts_with('.') {
                    continue;
                }

                let is_dir = metadata.is_dir();
                let size = metadata.len();
                entries.push((name, is_dir, size));
            }
        }
    }

    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let mut html = String::from("<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<title>Directory Listing</title>\n<style>\nbody { font-family: monospace; }\ntable { border-collapse: collapse; width: 100%; }\nth, td { text-align: left; padding: 5px; border-bottom: 1px solid #ddd; }\n</style>\n</head>\n<body>\n");
    html.push_str("<h1>Directory Listing</h1>\n");
    html.push_str("<table>\n<tr><th>Name</th><th>Size</th><th>Modified</th></tr>\n");

